.aj-layout-titlebar{width:100%;min-height:38px;display:flex;align-items:center;padding:10px 18px;border-bottom:1px solid #dbe3ee;background:#fff;color:#10233f;font:700 13px/1.35 Inter,"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
.aj-layout-titlebar strong{font-weight:700;font-size:13px}

/* solicitacoes.cliente.avaliar_experiencia · formulário de avaliação */
.evaluation-page{
  width:min(100%,720px);
  margin:0 auto;
  padding:22px 18px 48px;
}
.evaluation-intro{margin:0 2px 18px}
.evaluation-eyebrow{
  display:block;
  margin-bottom:7px;
  color:var(--gold);
  font-size:11px;
  font-weight:900;
  letter-spacing:.08em;
}
.evaluation-intro h1{
  margin:0;
  color:var(--primary);
  font-size:clamp(24px,6vw,32px);
  line-height:1.12;
}
.evaluation-intro p{
  margin:9px 0 0;
  color:var(--muted);
  font-size:13px;
  line-height:1.55;
}
.evaluation-form{display:grid;gap:12px}
.evaluation-card{
  border:1px solid var(--line);
  border-radius:16px;
  padding:17px;
  background:var(--surface);
}
.evaluation-professional{
  display:flex;
  gap:12px;
  align-items:center;
  margin-bottom:12px;
}
.evaluation-professional strong,
.evaluation-professional span{display:block}
.evaluation-professional strong{color:var(--primary);font-size:14px}
.evaluation-professional span{margin-top:3px;color:var(--muted);font-size:11px}
.evaluation-avatar{
  display:grid;
  width:46px;
  height:46px;
  flex:0 0 46px;
  place-items:center;
  border-radius:50%;
  background:#e8eef5;
  color:var(--primary);
  font-size:13px;
  font-weight:900;
}
.evaluation-question h2{
  margin:0;
  color:var(--primary);
  font-size:15px;
}
.evaluation-question p{
  margin:5px 0 12px;
  color:var(--muted);
  font-size:12px;
  line-height:1.5;
}
.star-field{margin:0;padding:0;border:0}
.star-field>small{
  display:block;
  margin-top:5px;
  color:var(--muted);
  font-size:10px;
}
.star-rating{
  display:inline-flex;
  flex-direction:row-reverse;
  justify-content:flex-end;
  gap:4px;
}
.star-rating input{
  position:absolute;
  width:1px;
  height:1px;
  opacity:0;
  pointer-events:none;
}
.star-rating label{
  display:inline-block;
  color:#c8d0da;
  font-size:34px;
  line-height:1;
  cursor:pointer;
  transition:transform .12s ease,color .12s ease;
}
.star-rating label:hover{transform:scale(1.06)}
.star-rating label:hover,
.star-rating label:hover~label,
.star-rating input:checked~label{color:var(--gold)}
.star-rating input:focus-visible+label{
  outline:2px solid var(--primary-soft);
  outline-offset:3px;
  border-radius:5px;
}
.evaluation-comment>span{
  display:block;
  margin-bottom:8px;
  color:var(--primary);
  font-size:13px;
  font-weight:800;
}
.evaluation-comment>span small{
  color:var(--muted);
  font-size:10px;
  font-weight:700;
}
.evaluation-comment textarea{
  width:100%;
  min-height:120px;
  resize:vertical;
  border:1px solid var(--line);
  border-radius:12px;
  padding:12px 13px;
  background:#fff;
  color:var(--text);
  font:inherit;
  font-size:13px;
  line-height:1.5;
  outline:0;
}
.evaluation-comment textarea:focus{
  border-color:var(--primary-soft);
  box-shadow:0 0 0 3px rgba(23,60,107,.10);
}
.evaluation-comment>small{
  display:block;
  margin-top:7px;
  color:var(--muted);
  font-size:10px;
  line-height:1.45;
}
.evaluation-note{
  display:grid;
  gap:4px;
  border-radius:13px;
  padding:13px 14px;
  background:#f3f6fa;
}
.evaluation-note strong{
  color:var(--primary);
  font-size:11px;
}
.evaluation-note p{
  margin:0;
  color:var(--muted);
  font-size:10px;
  line-height:1.5;
}
.evaluation-actions{margin-top:4px}
.evaluation-submit{
  width:100%;
  min-height:54px;
  border:0;
  border-radius:13px;
  padding:14px 18px;
  background:var(--primary);
  color:#fff;
  font-size:14px;
  font-weight:800;
  cursor:pointer;
}
.sr-only{
  position:absolute!important;
  width:1px!important;
  height:1px!important;
  padding:0!important;
  margin:-1px!important;
  overflow:hidden!important;
  clip:rect(0,0,0,0)!important;
  white-space:nowrap!important;
  border:0!important;
}
@media(min-width:700px){
  .evaluation-page{padding-top:30px}
  .evaluation-card{padding:20px}
}

.aj-layout-drawer.prototype-drawer{position:fixed!important;inset:0!important;z-index:9998!important;display:none!important;pointer-events:none}.aj-layout-drawer.prototype-drawer.open{display:block!important;pointer-events:auto}
